/**
 * AegisOne — encrypted extension storage
 * =======================================
 * chrome.storage.local is plain JSON on disk, so anything left there (sign-in tokens, the local
 * security-event log with URLs the user visited) can be read by anyone with access to the profile
 * folder. Sensitive keys are therefore stored as AES-256-GCM ciphertext.
 *
 *   - The key is generated by WebCrypto as NON-EXTRACTABLE and kept in IndexedDB (extension
 *     origin) as a CryptoKey object: scripts in this extension can use it, but its bytes can
 *     never be read out, copied from the profile folder, or exported.
 *   - A fresh random 96-bit IV is used for every write; the storage key name is bound in as
 *     additional authenticated data so a ciphertext cannot be moved under another key.
 *   - Plaintext values written by an older version are still readable and are re-encrypted on the
 *     next write (transparent migration).
 *
 * Written as a classic script (no `export`) so the service worker, popup and content scripts can
 * all load it; it publishes `globalThis.AegisSecure`.
 */
(() => {
  if (globalThis.AegisSecure) return;

  const DB_NAME = "aegis_secure";
  const STORE = "keys";
  const KEY_ID = "storage-aes-gcm-v1";
  const MARK = "__aegis_enc";
  const enc = new TextEncoder();
  const dec = new TextDecoder();

  let _keyPromise = null;

  function _openDb() {
    return new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME, 1);
      req.onupgradeneeded = () => req.result.createObjectStore(STORE);
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }

  function _idb(db, mode, fn) {
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE, mode);
      const req = fn(tx.objectStore(STORE));
      tx.oncomplete = () => resolve(req.result);
      tx.onerror = () => reject(tx.error);
      tx.onabort = () => reject(tx.error);
    });
  }

  async function _getKey() {
    if (_keyPromise) return _keyPromise;
    _keyPromise = (async () => {
      const db = await _openDb();
      let key = await _idb(db, "readonly", (s) => s.get(KEY_ID));
      if (!key) {
        key = await crypto.subtle.generateKey({ name: "AES-GCM", length: 256 }, /* extractable */ false, ["encrypt", "decrypt"]);
        // Two contexts racing on first run: keep whichever key was stored first.
        await _idb(db, "readwrite", (s) => s.add(key, KEY_ID)).catch(() => {});
        key = (await _idb(db, "readonly", (s) => s.get(KEY_ID))) || key;
      }
      db.close();
      return key;
    })().catch((e) => { _keyPromise = null; throw e; });
    return _keyPromise;
  }

  const _b64 = (buf) => btoa(String.fromCharCode(...new Uint8Array(buf)));
  const _unb64 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

  async function _seal(name, value) {
    const key = await _getKey();
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const ct = await crypto.subtle.encrypt(
      { name: "AES-GCM", iv, additionalData: enc.encode(name) }, key, enc.encode(JSON.stringify(value)));
    return { [MARK]: 1, iv: _b64(iv), ct: _b64(ct) };
  }

  async function _open(name, stored) {
    if (!stored || typeof stored !== "object" || stored[MARK] !== 1) return stored;   // legacy plaintext
    try {
      const key = await _getKey();
      const pt = await crypto.subtle.decrypt(
        { name: "AES-GCM", iv: _unb64(stored.iv), additionalData: enc.encode(name) }, key, _unb64(stored.ct));
      return JSON.parse(dec.decode(pt));
    } catch (_) {
      return undefined;   // tampered, or the key was lost (profile restored elsewhere): treat as empty
    }
  }

  /** Like chrome.storage.local.get(keys) but decrypts protected values. */
  async function get(keys) {
    const raw = await chrome.storage.local.get(keys);
    const out = {};
    for (const [k, v] of Object.entries(raw)) {
      const val = await _open(k, v);
      if (val !== undefined) out[k] = val;
    }
    return out;
  }

  /** Like chrome.storage.local.set(obj) but encrypts every value. */
  async function set(obj) {
    const sealed = {};
    for (const [k, v] of Object.entries(obj)) sealed[k] = await _seal(k, v);
    await chrome.storage.local.set(sealed);
  }

  async function remove(keys) {
    await chrome.storage.local.remove(keys);
  }

  globalThis.AegisSecure = { get, set, remove };
})();
